{
  "description": "A corrected HSTU cold-start baseline for sequential recommendation on four Amazon categories: Movies_and_TV, Industrial_and_Scientific, Electronics, and CDs_and_Vinyl. Train one independent HSTU model per category and select changes using macro-average validation HR@10.",
  "motivation": "Establish a reproducible HSTU comparison under fixed data splits, seeds, evaluation candidates, and compute limits, while preventing target leakage and inconsistent training versus inference implementations.",
  "implementation_notes": "Use preprocessing seed 0 and training seed 42, at most 200 epochs, and 200 batches per epoch. Preserve the supplied HSTU backbone, category routing, and DATA_DIR = os.environ['GAGC_DATA_DIR']. For left-padded histories, read the final nonpadding position, never count-1. Keep checkpoints, the predictor writer, working/predict.py, ModelView interfaces, and diagnostic probes consistent. Each category must load exactly one trained model; independent predictor fusion is prohibited. Use only permitted public data and validation feedback. The supplied description contains no baseline source code, architectural details, or measured results.",
  "pseudocode": "Set preprocessing seed to 0 and training seed to 42.\nFor each of the four categories:\n    Load the supplied fixed splits from GAGC_DATA_DIR.\n    Initialize the supplied corrected HSTU model.\n    Train within the epoch, batch, and shared compute limits.\n    Preserve family-compatible diagnostics and prediction interfaces.\n    Save one selected model checkpoint beneath the trial directory.\nGenerate working/predict.py with matching architecture and category routing.\nLet the host evaluate validation HR@10 using its pinned protocol.\nCompare proposals by mean validation HR@10 across all four categories.",
  "originality": {
    "score": 2,
    "positive": "Provides a carefully constrained, family-specific experimental baseline.",
    "negative": "Describes an evaluation setup rather than a new modeling contribution; no novel HSTU mechanism is specified."
  },
  "future_potential": {
    "score": 7,
    "positive": "Supports controlled exploration of jointly trained HSTU layers, losses, sampling strategies, and optimization settings.",
    "negative": "Improvement remains unverified; search must fit the shared 43,200 GPU-second budget."
  },
  "code_difficulty": {
    "score": 6,
    "positive": "The supplied corrected baseline and fixed evaluator should reduce initial implementation work.",
    "negative": "Architecture changes require synchronized training, checkpoint loading, embedded predictor generation, and family-specific diagnostics. Scores use a 1–10 scale, with higher difficulty indicating harder implementation."
  }
}
